fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Each special guest needs one cookie from each pile,
    // so neither pile can have fewer than m cookies.
    if a < m || b < m {
        return false;
    }

    // To avoid u8 overflow when summing, promote to u16.
    let total_available = (a as u16) + (b as u16);
    // Regular guests need 1 cookie each, special guests need 2 each.
    let total_required = (n as u16) + 2 * (m as u16);

    // Check that we have enough cookies in total.
    total_available >= total_required
}

